    "<svg viewBox=\"0 0 254 132\" width=\"254\" role=\"img\" aria-label=\"Seçenek C tablosu\"><rect x=\"1\" y=\"1\" width=\"252\" height=\"130\" fill=\"#fff\" stroke=\"#16a34a\"/><rect x=\"1\" y=\"1\" width=\"252\" height=\"38\" fill=\"#dcfce7\" stroke=\"#16a34a\"/><g font-size=\"12\" text-anchor=\"middle\" fill=\"#1e293b\"><text x=\"47.0\" y=\"24.0\" font-weight=\"bold\">Yayınevi</text><text x=\"132.0\" y=\"16.5\" font-weight=\"bold\">Satılan</text><text x=\"132.0\" y=\"31.5\" font-weight=\"bold\">Kitap</text><text x=\"212.0\" y=\"16.5\" font-weight=\"bold\">Ziyaretçi</text><text x=\"212.0\" y=\"31.5\" font-weight=\"bold\">Sayısı</text><line x1=\"1\" y1=\"39\" x2=\"253\" y2=\"39\" stroke=\"#16a34a\" stroke-width=\"0.8\"/><text x=\"47.0\" y=\"54.8\" font-weight=\"bold\">Martı</text><text x=\"132.0\" y=\"54.8\">4.200</text><text x=\"212.0\" y=\"54.8\">6.500</text><line x1=\"1\" y1=\"62\" x2=\"253\" y2=\"62\" stroke=\"#16a34a\" stroke-width=\"0.8\"/><text x=\"47.0\" y=\"77.8\" font-weight=\"bold\">Pusula</text><text x=\"132.0\" y=\"77.8\">2.600</text><text x=\"212.0\" y=\"77.8\">3.900</text><line x1=\"1\" y1=\"85\" x2=\"253\" y2=\"85\" stroke=\"#16a34a\" stroke-width=\"0.8\"/><text x=\"47.0\" y=\"100.8\" font-weight=\"bold\">Yaprak</text><text x=\"132.0\" y=\"100.8\">1.800</text><text x=\"212.0\" y=\"100.8\">5.200</text><line x1=\"1\" y1=\"108\" x2=\"253\" y2=\"108\" stroke=\"#16a34a\" stroke-width=\"0.8\"/><text x=\"47.0\" y=\"123.8\" font-weight=\"bold\">Çınar</text><text x=\"132.0\" y=\"123.8\">3.700</text><text x=\"212.0\" y=\"123.8\">7.100</text><line x1=\"93\" y1=\"1\" x2=\"93\" y2=\"131\" stroke=\"#16a34a\" stroke-width=\"0.8\"/><line x1=\"171\" y1=\"1\" x2=\"171\" y2=\"131\" stroke=\"#16a34a\" stroke-width=\"0.8\"/></g></svg>",
    "<svg viewBox=\"0 0 254 132\" width=\"254\" role=\"img\" aria-label=\"Seçenek D tablosu\"><rect x=\"1\" y=\"1\" width=\"252\" height=\"130\" fill=\"#fff\" stroke=\"#16a34a\"/><rect x=\"1\" y=\"1\" width=\"252\" height=\"38\" fill=\"#dcfce7\" stroke=\"#16a34a\"/><g font-size=\"12\" text-anchor=\"middle\" fill=\"#1e293b\"><text x=\"47.0\" y=\"24.0\" font-weight=\"bold\">Yayınevi</text><text x=\"132.0\" y=\"16.5\" font-weight=\"bold\">Satılan</text><text x=\"132.0\" y=\"31.5\" font-weight=\"bold\">Kitap</text><text x=\"212.0\" y=\"16.5\" font-weight=\"bold\">Ziyaretçi</text><text x=\"212.0\" y=\"31.5\" font-weight=\"bold\">Sayısı</text><line x1=\"1\" y1=\"39\" x2=\"253\" y2=\"39\" stroke=\"#16a34a\" stroke-width=\"0.8\"/><text x=\"47.0\" y=\"54.8\" font-weight=\"bold\">Martı</text><text x=\"132.0\" y=\"54.8\">4.200</text><text x=\"212.0\" y=\"54.8\">6.500</text><line x1=\"1\" y1=\"62\" x2=\"253\" y2=\"62\" stroke=\"#16a34a\" stroke-width=\"0.8\"/><text x=\"47.0\" y=\"77.8\" font-weight=\"bold\">Pusula</text><text x=\"132.0\" y=\"77.8\">2.500</text><text x=\"212.0\" y=\"77.8\">4.000</text><line x1=\"1\" y1=\"85\" x2=\"253\" y2=\"85\" stroke=\"#16a34a\" stroke-width=\"0.8\"/><text x=\"47.0\" y=\"100.8\" font-weight=\"bold\">Yaprak</text><text x=\"132.0\" y=\"100.8\">2.100</text><text x=\"212.0\" y=\"100.8\">5.400</text><line x1=\"1\" y1=\"108\" x2=\"253\" y2=\"108\" stroke=\"#16a34a\" stroke-width=\"0.8\"/><text x=\"47.0\" y=\"123.8\" font-weight=\"bold\">Çınar</text><text x=\"132.0\" y=\"123.8\">4.400</text><text x=\"212.0\" y=\"123.8\">6.900</text><line x1=\"93\" y1=\"1\" x2=\"93\" y2=\"131\" stroke=\"#16a34a\" stroke-width=\"0.8\"/><line x1=\"171\" y1=\"1\" x2=\"171\" y2=\"131\" stroke=\"#16a34a\" stroke-width=\"0.8\"/></g></svg>"
