    "<svg viewBox=\"0 0 190 64\" width=\"190\" role=\"img\" aria-label=\"Kilit şifresi 2 7 2 1\"><g font-size=\"22\" font-weight=\"bold\" fill=\"#1e293b\"><rect x=\"1\" y=\"1\" width=\"188\" height=\"62\" rx=\"10\" fill=\"#e2e8f0\" stroke=\"#475569\" stroke-width=\"2\"/><rect x=\"14\" y=\"12\" width=\"34\" height=\"40\" rx=\"4\" fill=\"#fff\" stroke=\"#475569\"/><text x=\"31\" y=\"40\" text-anchor=\"middle\">2</text><rect x=\"56\" y=\"12\" width=\"34\" height=\"40\" rx=\"4\" fill=\"#fff\" stroke=\"#475569\"/><text x=\"73\" y=\"40\" text-anchor=\"middle\">7</text><rect x=\"98\" y=\"12\" width=\"34\" height=\"40\" rx=\"4\" fill=\"#fff\" stroke=\"#475569\"/><text x=\"115\" y=\"40\" text-anchor=\"middle\">2</text><rect x=\"140\" y=\"12\" width=\"34\" height=\"40\" rx=\"4\" fill=\"#fff\" stroke=\"#475569\"/><text x=\"157\" y=\"40\" text-anchor=\"middle\">1</text></g></svg>",
    "<svg viewBox=\"0 0 190 64\" width=\"190\" role=\"img\" aria-label=\"Kilit şifresi 8 6 3 4\"><g font-size=\"22\" font-weight=\"bold\" fill=\"#1e293b\"><rect x=\"1\" y=\"1\" width=\"188\" height=\"62\" rx=\"10\" fill=\"#e2e8f0\" stroke=\"#475569\" stroke-width=\"2\"/><rect x=\"14\" y=\"12\" width=\"34\" height=\"40\" rx=\"4\" fill=\"#fff\" stroke=\"#475569\"/><text x=\"31\" y=\"40\" text-anchor=\"middle\">8</text><rect x=\"56\" y=\"12\" width=\"34\" height=\"40\" rx=\"4\" fill=\"#fff\" stroke=\"#475569\"/><text x=\"73\" y=\"40\" text-anchor=\"middle\">6</text><rect x=\"98\" y=\"12\" width=\"34\" height=\"40\" rx=\"4\" fill=\"#fff\" stroke=\"#475569\"/><text x=\"115\" y=\"40\" text-anchor=\"middle\">3</text><rect x=\"140\" y=\"12\" width=\"34\" height=\"40\" rx=\"4\" fill=\"#fff\" stroke=\"#475569\"/><text x=\"157\" y=\"40\" text-anchor=\"middle\">4</text></g></svg>"
