    "<svg viewBox=\"0 0 270 200\" width=\"270\" role=\"img\" aria-label=\"Seçenek grafiği: kulüplerdeki kız ve erkek öğrenci sayısı\"><g font-size=\"11\" fill=\"#1e293b\"><text x=\"4\" y=\"13\">Öğrenci sayısı</text><rect x=\"203\" y=\"4\" width=\"12\" height=\"12\" fill=\"#3b82f6\"/><text x=\"219\" y=\"14\">Erkek</text><rect x=\"160\" y=\"4\" width=\"12\" height=\"12\" fill=\"#ec4899\"/><text x=\"176\" y=\"14\">Kız</text><line x1=\"40\" y1=\"170.0\" x2=\"260\" y2=\"170.0\" stroke=\"#e2e8f0\"/><text x=\"36\" y=\"173.5\" text-anchor=\"end\">0</text><line x1=\"40\" y1=\"142.8\" x2=\"260\" y2=\"142.8\" stroke=\"#e2e8f0\"/><text x=\"36\" y=\"146.3\" text-anchor=\"end\">4</text><line x1=\"40\" y1=\"115.6\" x2=\"260\" y2=\"115.6\" stroke=\"#e2e8f0\"/><text x=\"36\" y=\"119.1\" text-anchor=\"end\">8</text><line x1=\"40\" y1=\"88.4\" x2=\"260\" y2=\"88.4\" stroke=\"#e2e8f0\"/><text x=\"36\" y=\"91.9\" text-anchor=\"end\">12</text><line x1=\"40\" y1=\"61.2\" x2=\"260\" y2=\"61.2\" stroke=\"#e2e8f0\"/><text x=\"36\" y=\"64.7\" text-anchor=\"end\">16</text><line x1=\"40\" y1=\"34.0\" x2=\"260\" y2=\"34.0\" stroke=\"#e2e8f0\"/><text x=\"36\" y=\"37.5\" text-anchor=\"end\">20</text><line x1=\"40\" y1=\"30\" x2=\"40\" y2=\"170\" stroke=\"#334155\"/><line x1=\"40\" y1=\"170\" x2=\"260\" y2=\"170\" stroke=\"#334155\"/><rect x=\"51.0\" y=\"88.4\" width=\"24.7\" height=\"81.6\" fill=\"#ec4899\" stroke=\"#334155\" stroke-width=\"0.5\"/><text x=\"63.8\" y=\"85.4\" text-anchor=\"middle\">12</text><rect x=\"76.7\" y=\"88.4\" width=\"24.7\" height=\"81.6\" fill=\"#3b82f6\" stroke=\"#334155\" stroke-width=\"0.5\"/><text x=\"89.5\" y=\"85.4\" text-anchor=\"middle\">12</text><text x=\"76.7\" y=\"185.0\" text-anchor=\"middle\">Satranç</text><rect x=\"124.3\" y=\"47.6\" width=\"24.7\" height=\"122.4\" fill=\"#ec4899\" stroke=\"#334155\" stroke-width=\"0.5\"/><text x=\"137.2\" y=\"44.6\" text-anchor=\"middle\">18</text><rect x=\"150.0\" y=\"102.0\" width=\"24.7\" height=\"68.0\" fill=\"#3b82f6\" stroke=\"#334155\" stroke-width=\"0.5\"/><text x=\"162.8\" y=\"99.0\" text-anchor=\"middle\">10</text><text x=\"150.0\" y=\"185.0\" text-anchor=\"middle\">Drama</text><rect x=\"197.7\" y=\"74.8\" width=\"24.7\" height=\"95.2\" fill=\"#ec4899\" stroke=\"#334155\" stroke-width=\"0.5\"/><text x=\"210.5\" y=\"71.8\" text-anchor=\"middle\">14</text><rect x=\"223.3\" y=\"74.8\" width=\"24.7\" height=\"95.2\" fill=\"#3b82f6\" stroke=\"#334155\" stroke-width=\"0.5\"/><text x=\"236.2\" y=\"71.8\" text-anchor=\"middle\">14</text><text x=\"223.3\" y=\"185.0\" text-anchor=\"middle\">Bilim</text></g></svg>"
