    "<svg viewBox=\"0 0 200 88\" width=\"200\" role=\"img\" aria-label=\"Seçenek: şarj istasyonu ekranı saat 06.30\"><g font-size=\"12\" fill=\"#1e293b\"><rect x=\"1\" y=\"1\" width=\"198\" height=\"86\" rx=\"8\" fill=\"#fff\" stroke=\"#64748b\" stroke-width=\"1.5\"/><text x=\"100\" y=\"22\" text-anchor=\"middle\" font-weight=\"bold\" font-size=\"13\">Saat 06.30</text><line x1=\"10\" y1=\"30\" x2=\"190\" y2=\"30\" stroke=\"#cbd5e1\"/><text x=\"14\" y=\"50\">Tarife:</text><text x=\"186\" y=\"50\" text-anchor=\"end\" font-weight=\"bold\">Gece</text><text x=\"14\" y=\"74\">Şarj:</text><text x=\"186\" y=\"74\" text-anchor=\"end\" font-weight=\"bold\">Hızlı</text></g></svg>"
