    "<svg viewBox=\"0 0 230 112\" width=\"230\" role=\"img\" aria-label=\"Seçenek: tünel giriş tabelası saat 12.00\"><g font-size=\"12\" fill=\"#1e293b\"><rect x=\"1\" y=\"1\" width=\"228\" height=\"110\" rx=\"8\" fill=\"#fff\" stroke=\"#64748b\" stroke-width=\"1.5\"/><text x=\"115\" y=\"22\" text-anchor=\"middle\" font-weight=\"bold\" font-size=\"13\">Saat 12.00</text><line x1=\"10\" y1=\"30\" x2=\"220\" y2=\"30\" stroke=\"#cbd5e1\"/><text x=\"14\" y=\"50\">Sol şerit:</text><text x=\"216\" y=\"50\" text-anchor=\"end\" font-weight=\"bold\">Kapalı</text><text x=\"14\" y=\"74\">Sağ şerit:</text><text x=\"216\" y=\"74\" text-anchor=\"end\" font-weight=\"bold\">Açık</text><text x=\"14\" y=\"98\">Hız sınırı (km/sa):</text><text x=\"216\" y=\"98\" text-anchor=\"end\" font-weight=\"bold\">40</text></g></svg>",
    "<svg viewBox=\"0 0 230 112\" width=\"230\" role=\"img\" aria-label=\"Seçenek: tünel giriş tabelası saat 08.00\"><g font-size=\"12\" fill=\"#1e293b\"><rect x=\"1\" y=\"1\" width=\"228\" height=\"110\" rx=\"8\" fill=\"#fff\" stroke=\"#64748b\" stroke-width=\"1.5\"/><text x=\"115\" y=\"22\" text-anchor=\"middle\" font-weight=\"bold\" font-size=\"13\">Saat 08.00</text><line x1=\"10\" y1=\"30\" x2=\"220\" y2=\"30\" stroke=\"#cbd5e1\"/><text x=\"14\" y=\"50\">Sol şerit:</text><text x=\"216\" y=\"50\" text-anchor=\"end\" font-weight=\"bold\">Kapalı</text><text x=\"14\" y=\"74\">Sağ şerit:</text><text x=\"216\" y=\"74\" text-anchor=\"end\" font-weight=\"bold\">Açık</text><text x=\"14\" y=\"98\">Hız sınırı (km/sa):</text><text x=\"216\" y=\"98\" text-anchor=\"end\" font-weight=\"bold\">60</text></g></svg>"
